<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$rows=$pdo->query("SELECT r.id,r.event_id,r.parent_round_id,r.round_type,r.division,r.scoring_mode,r.status,e.name event_name,e.event_date FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.status NOT IN('completed','archived') ORDER BY e.event_date DESC,e.name,r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Screen Projector | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.event-card{border:0;border-radius:16px}.round-badge{text-transform:uppercase;letter-spacing:.08em}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring/">BDC Scoring</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="mb-4"><div class="text-uppercase text-danger fw-bold small">9:16 Event Presentation</div><h1 class="h2">Live Screen Projector</h1><p class="text-muted">Choose a live competition round to control audience-safe projection screens.</p></div><div class="row g-3"><?php foreach($rows as $r):?><div class="col-lg-6"><div class="card event-card shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between gap-2"><div><h2 class="h5 mb-1"><?=e($r['event_name'])?></h2><div class="text-muted"><?=e(ucwords(str_replace('_',' ',$r['division'])))?></div></div><span class="badge text-bg-dark round-badge"><?=e($r['round_type'])?></span></div><div class="mt-3 small">Mode: <strong><?=e(strtoupper($r['scoring_mode']??'manual'))?></strong> · Status: <?=e(ucwords(str_replace('_',' ',$r['status'])))?></div><a class="btn btn-danger w-100 mt-3" href="control.php?round_id=<?=(int)$r['id']?>">Projection Control</a></div></div></div><?php endforeach;?><?php if(!$rows):?><div class="col-12"><div class="alert alert-secondary">No live scoring rounds are currently available.</div></div><?php endif;?></div></main></body></html>